WITH cleaned AS (SELECT id, order_id, method, amount, paid_at, status, CONCAT_WS('-', status, method) status_method_key FROM payments WHERE paid_at > TIMESTAMP '2024-04-07 10:00:00' AND order_id IS NOT NULL), flagged AS (SELECT *, CASE WHEN LAG(paid_at) OVER (PARTITION BY status ORDER BY paid_at, id) IS NULL OR paid_at > LAG(paid_at) OVER (PARTITION BY status ORDER BY paid_at, id) + INTERVAL '30' DAY THEN 1 ELSE 0 END AS new_group_flag FROM cleaned), sessionized AS (SELECT *, SUM(new_group_flag) OVER (PARTITION BY status ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM flagged) SELECT DATE_TRUNC('QUARTER', paid_at) AS quarter_start, APPROX_PERCENTILE(new_group_flag, ARRAY(0.25, 0.5, 0.75)) AS new_group_flag_quartiles, STDDEV_SAMP(amount) AS amount_stddev FROM sessionized GROUP BY DATE_TRUNC('QUARTER', paid_at)
